method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0 // The input list must not be empty
    ensures |result| == |xs| - 1 // The result length is one less than the input length
    ensures forall i :: 0 <= i < |result| ==> result[i] == xs[i + 1] * (i + 1) // Each coefficient is derived correctly
{
    var n := |xs|;
    var res := new int[n - 1];
    var i := 0;
    while i < n - 1
        invariant 0 <= i <= n - 1 // i is within the valid range
        invariant |res| == i // The length of res equals the number of computed derivatives so far
    {
        res[i] := xs[i + 1] * (i + 1);
        i := i + 1;
    }
    result := res;
}
